"use client";

import { useState, useEffect } from "react";

type StarButtonProps = {
  docPath: string;
  className?: string;
};

export function StarButton({ docPath, className = "" }: StarButtonProps) {
  const [isStarred, setIsStarred] = useState(false);

  useEffect(() => {
    // Load starred state from localStorage
    const starred = localStorage.getItem("starred-docs");
    if (starred) {
      const starredPaths = JSON.parse(starred);
      setIsStarred(starredPaths.includes(docPath));
    }
  }, [docPath]);

  const toggleStar = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const starred = localStorage.getItem("starred-docs");
    const starredPaths = starred ? JSON.parse(starred) : [];

    if (isStarred) {
      // Remove from starred
      const updated = starredPaths.filter((path: string) => path !== docPath);
      localStorage.setItem("starred-docs", JSON.stringify(updated));
      setIsStarred(false);
    } else {
      // Add to starred
      starredPaths.push(docPath);
      localStorage.setItem("starred-docs", JSON.stringify(starredPaths));
      setIsStarred(true);
    }

    // Dispatch custom event to notify other components
    window.dispatchEvent(new CustomEvent("starred-changed"));
  };

  return (
    <button
      onClick={toggleStar}
      className={`${className} transition-all hover:scale-110 active:scale-95`}
      aria-label={isStarred ? "Unstar document" : "Star document"}
    >
      <svg
        className={`w-5 h-5 transition-colors ${
          isStarred
            ? "fill-amber-400 text-amber-400"
            : "fill-none text-slate-500 hover:text-amber-400"
        }`}
        viewBox="0 0 24 24"
        stroke="currentColor"
        strokeWidth={isStarred ? 0 : 1.5}
      >
        <path
          strokeLinecap="round"
          strokeLinejoin="round"
          d="M11.48 3.499a.562.562 0 011.04 0l2.125 5.111a.563.563 0 00.475.345l5.518.442c.499.04.701.663.321.988l-4.204 3.602a.563.563 0 00-.182.557l1.285 5.385a.562.562 0 01-.84.61l-4.725-2.885a.563.563 0 00-.586 0L6.982 20.54a.562.562 0 01-.84-.61l1.285-5.386a.562.562 0 00-.182-.557l-4.204-3.602a.563.563 0 01.321-.988l5.518-.442a.563.563 0 00.475-.345L11.48 3.5z"
        />
      </svg>
    </button>
  );
}

// Helper function to check if a doc is starred
export function isDocStarred(docPath: string): boolean {
  if (typeof window === "undefined") return false;
  const starred = localStorage.getItem("starred-docs");
  if (!starred) return false;
  const starredPaths = JSON.parse(starred);
  return starredPaths.includes(docPath);
}

// Helper function to get all starred paths
export function getStarredDocs(): string[] {
  if (typeof window === "undefined") return [];
  const starred = localStorage.getItem("starred-docs");
  if (!starred) return [];
  return JSON.parse(starred);
}

